-- Synthetic fixture (no prod literal): org prefix f0f0f0f0 (target) + 99999999 (other org); one backfill run per case; unit results = the
-- shapes the github tests route stores (result.incomplete = [{component, cause, count}]). Case runs (8-hex run prefixes):
--   a1a1a1a1 ADV-ONLY : 1 success unit, incomplete report_member:malformed:6 + run_reports:per_run_cap:141 (all advancing) -> stmt2 0, stmt3 1
--   b2b2b2b2 INVENTORY: 1 success unit, incomplete run_inventory:page_budget_exhausted:1 (not a pair)         -> stmt2 1, stmt3 0
--   c3c3c3c3 MIXED    : 1 success unit, incomplete run_reports:per_run_cap:9 + run_artifacts:page_budget_exhausted:2 (2nd not a pair) -> stmt2 1, stmt3 0
--   d4d4d4d4 SHAPES   : 1 failed unit with incomplete as an OBJECT (not an array), 1 success unit with an entry with no cause,
--                       1 success unit with no incomplete, 1 running unit with an advancing entry (not terminal) -> stmt2 2, stmt3 0
--   e5e5e5e5 TWO      : 2 success units: one advancing-only (late_rerun_reports:listing_saturated + run_jobs:per_run_cap), one with
--                       report_member:per_run_cap (per_run_cap is not a report_member cause) -> stmt2 1, stmt3 1
--   f6f6f6f6 OTHERORG : a run_inventory (non-advancing) unit under org 99999999 -> with the target org prefix: stmt0 runs 0, stmt2 0, stmt3 0
ANALYZE public.organizations; ANALYZE public.integration_sources; ANALYZE public.sync_runs; ANALYZE public.sync_run_units; ANALYZE public.sync_run_unit_chunk_checkpoints;
